window.docContents[160].resolve({"/Poly/#Logical-Foundations--Poly___-Polymorphism-and-Higher-Order-Functions--Functions-as-Data":{"contents":"Like most modern programming languages — especially other\n\"functional\" languages, including OCaml, Haskell, Racket, Scala,\nClojure, etc. — Lean treats functions as first-class citizens,\nallowing them to be passed as arguments to other functions,\nreturned as results, stored in data structures, etc.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Poly: Polymorphism and Higher-Order Functions","header":"6.2. Functions as Data","id":"/Poly/#Logical-Foundations--Poly___-Polymorphism-and-Higher-Order-Functions--Functions-as-Data"}});